package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseN1MigrationTest extends MigrationTestSupport {
 @Test void populatedM3PreservesHistoricalRequestsWithoutRetrofittingDeadlines(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_n1_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("51").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID a=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('n1-legacy-a@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class),b=db.queryForObject("INSERT INTO users(email,password_hash,status,email_verified) VALUES('n1-legacy-b@example.test','synthetic-only','ACTIVE',TRUE) RETURNING id",UUID.class),request=UUID.randomUUID();db.update("INSERT INTO profiles(user_id,username,display_name) VALUES(?,'n1_legacy_a','Preserved member'),(?,'n1_legacy_b','Preserved listener')",a,b);db.update("INSERT INTO live_support_requests(id,member_id,listener_id,client_request_id,presence_seconds,reconnect_seconds,expires_at) VALUES(?,?,?,?,45,120,CURRENT_TIMESTAMP+INTERVAL '1 day')",request,a,b,UUID.randomUUID());var before=db.queryForList("SELECT id,member_id,listener_id,status,created_at,expires_at FROM live_support_requests");var profiles=db.queryForList("SELECT * FROM profiles");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();f.migrate();f.validate();assertThat(db.queryForList("SELECT id,member_id,listener_id,status,created_at,expires_at FROM live_support_requests")).isEqualTo(before);assertThat(db.queryForList("SELECT * FROM profiles")).isEqualTo(profiles);assertThat(db.queryForObject("SELECT planned_ends_at FROM live_support_requests WHERE id=?",Object.class,request)).isNull();assertThat(db.queryForObject("SELECT planned_seconds FROM live_support_requests WHERE id=?",Integer.class,request)).isNull();assertThat(db.queryForObject("SELECT count(*) FROM listener_bookings",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM listener_calendar_rules",Integer.class)).isZero();
  }finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
